async function searchOxfordDict() {
    const word = document.getElementById('dict-search-input').value.trim();
    if (!word) return;
    const box = document.getElementById('dict-modal-result');
    box.style.display = 'block';
    box.innerHTML = "<p>🔍 Đang tra từ điển Oxford...</p>";

    try {
        const res = await fetch(`/api/dictionary?word=${encodeURIComponent(word)}`);
        const result = await res.json();
        if (result.found && result.data) {
            const d = result.data;
            box.innerHTML = `
                <div style="display:flex; justify-content:space-between; align-items:center;">
                    <h3 style="color:#231F20; font-size:1.15rem;">📖 Oxford Standard: <span style="color:#C05621;">${d.word}</span> <span style="color:#786E6E; font-size:0.85rem;">${d.ipa}</span></h3>
                    <button class="speech-icon-btn" onclick="speakText('${d.word}')">🔊 Phát âm từ</button>
                </div>
                <p style="margin-top:0.4rem;"><strong>Loại từ:</strong> <em style="color:#C05621;">${d.pos}</em> | <strong>Nghĩa VI:</strong> <strong style="color:#276749;">${d.vi}</strong></p>
                <p style="margin-top:0.4rem; color:#4A4244;"><strong>Định nghĩa:</strong> ${d.def}</p>
                <p style="margin-top:0.4rem; font-style:italic; color:#524B4B;"><strong>Ví dụ:</strong> "${d.ex}" <button class="speech-icon-btn" onclick="speakText('${d.ex.replace(/'/g, "\\'")}}')">🔊 Đọc ví dụ</button></p>
            `;
        }
    } catch (e) {
        box.innerHTML = `<p style="color:#C53030;">Lỗi tra từ: ${e.message}</p>`;
    }
}

async function fetchLessonsAndRender() {
    try {
        const res = await fetch('/api/lessons?t=' + Date.now());
        if (res.ok) {
            const data = await res.json();
            let fetched = [];
            if (Array.isArray(data)) fetched = data;
            else if (data && Array.isArray(data.lessons)) fetched = data.lessons;
            if (fetched.length > 0) globalLessons = fetched;
        }
    } catch (e) {
        console.warn("Using bulletproof preply schedule fallback lessons:", e.message);
    }
    
    updateCourseMetrics();
    renderSidebarMenu();
    if (globalLessons.length > 0) selectLesson(globalLessons[0].id);
}

function updateCourseMetrics() {
    const total = globalLessons.length || 8;
    const completed = globalLessons.filter(l => (l.status || '').toLowerCase().includes('completed')).length || 1;
    const percent = Math.round((completed / total) * 100);
    
    const valEl = document.getElementById('course-progress-value');
    const fillEl = document.getElementById('course-progress-fill');
    if (valEl) valEl.innerText = `${completed} / ${total} Buổi (${percent}%)`;
    if (fillEl) fillEl.style.width = `${percent}%`;
}

function renderSidebarMenu() {
    const sidebar = document.getElementById('sidebar-lesson-list');
    sidebar.innerHTML = globalLessons.map(l => {
        const dateStr = l.scheduleDate || preplySchedules[l.id] || 'Monday, Aug 10, 2026 (22:00 - 22:50)';
        return `
            <div class="sidebar-item ${l.id === activeLessonId ? 'active' : ''}" onclick="selectLesson(${l.id})">
                <div><strong>Buổi ${l.id < 10 ? '0' + l.id : l.id}:</strong> ${l.title.replace(/^Lesson \d+:\s*/i, '')}</div>
                <div class="sidebar-item-date">📅 ${dateStr}</div>
            </div>
        `;
    }).join('');
}

